import concurrent.futures,datetime,hashlib,json,pathlib,re,subprocess,sys
root=pathlib.Path(__file__).resolve().parent
sha="408ededd1764cd45e156a42e2c20b6bad17862bc"
label=sys.argv[1]
assert re.fullmatch(r"[a-z0-9-]+",label)
def capture(run):
    cmd=["gh","run","view",run,"--repo","wmqfl861/gstack861"]
    result=subprocess.run([*cmd,"--json","headSha,status,conclusion,jobs,url,event"],capture_output=True)
    assert result.returncode==0,result.stderr.decode()
    meta=json.loads(result.stdout);assert meta["headSha"]==sha
    with (root/"publication"/f"ci-{run}-{label}.json").open("xb") as out:out.write(result.stdout)
    summary={"run":run,"head":sha,"event":meta["event"],"url":meta["url"],"status":meta["status"],"conclusion":meta["conclusion"],"jobs":[{k:j[k] for k in ("name","status","conclusion")} for j in meta["jobs"]]}
    if meta["status"]=="completed":
        logpath=root/"publication"/f"ci-{run}-full.log"
        if not logpath.exists():
            raw=subprocess.run([*cmd,"--log"],capture_output=True);assert raw.returncode==0,raw.stderr.decode()
            with logpath.open("xb") as out:out.write(raw.stdout)
        raw=logpath.read_bytes();summary["log_sha256"]=hashlib.sha256(raw).hexdigest();summary["log_bytes"]=len(raw)
        totals={};diagnostics=[];failures=[];environment=[]
        lines=raw.decode().splitlines()
        for i,line in enumerate(lines):
            cols=line.split("\t",2)
            if len(cols)!=3:continue
            job,step,body=cols;body=re.sub(r"^\S+ ","",body)
            if step=="Run npm test":
                match=re.match(r"# (tests|suites|pass|fail|cancelled|skipped) (\d+)",body)
                if match:totals.setdefault(job,{})[match[1]]=int(match[2])
                if "actualPlatform" in body:diagnostics.append({"job":job,"text":body})
                if body.startswith("not ok"):failures.append(body)
            if step=="Set up job" and ("Operating System" in body or "Microsoft Windows" in body or "windows-202" in body or "Ubuntu" in body):environment.append({"job":job,"lines":lines[i:i+4]})
        summary.update(tests=totals,diagnostics=diagnostics,failures=failures,environment=environment)
        summarypath=root/"publication"/f"ci-{run}-completed-summary.json"
        if summarypath.exists():assert json.loads(summarypath.read_text())==summary
        else:
            with summarypath.open("x") as out:json.dump(summary,out,indent=2);out.write("\n")
    return summary
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as executor:
    results=list(executor.map(capture,["41096155740","41096165326"]))
for value in results:print(json.dumps(value,ensure_ascii=False))
